android.extraProguardRules:
# Vosk calls its native library through JNA, by reflection: R8 must keep it.
# JNA's desktop-only window helpers reference java.awt, absent on Android.
-dontwarn java.awt.**
-keep class com.sun.jna.** { *; }
-keepclassmembers class * extends com.sun.jna.** { public *; }
-keep class org.vosk.** { *; }
